import os
import json
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

DATA_DIR = "/workdir/data"

# Ensure data directory exists
os.makedirs(DATA_DIR, exist_ok=True)


class CreateQueueRequest(BaseModel):
    name: str

class SendMessageRequest(BaseModel):
    content: str


@app.post("/queues")
def create_queue(request: CreateQueueRequest):
    queue_name = request.name
    queue_path = os.path.join(DATA_DIR, queue_name)
    # Check if queue already exists
    if os.path.exists(queue_path):
        raise HTTPException(status_code=400, detail="Queue already exists")
    # Create the queue directory (empty)
    os.makedirs(queue_path, exist_ok=True)
    return {"name": queue_name}


@app.post("/queues/{name}/messages")
def send_message(name: str, request: SendMessageRequest):
    queue_name = name
    queue_path = os.path.join(DATA_DIR, queue_name)
    if not os.path.exists(queue_path):
        raise HTTPException(status_code=404, detail="Queue not found")
    # Read existing messages
    messages_file = os.path.join(queue_path, "messages.jsonl")
    messages = []
    if os.path.exists(messages_file):
        with open(messages_file, "r") as f:
            for line in f:
                line = line.strip()
                if line:
                    messages.append(json.loads(line))
    # Add new message
    new_message = {"content": request.content}
    messages.append(new_message)
    # Write back
    with open(messages_file, "w") as f:
        for msg in messages:
            f.write(json.dumps(msg) + "\n")
    return {"content": request.content}


@app.get("/queues/{name}/messages")
def receive_message(name: str):
    queue_name = name
    queue_path = os.path.join(DATA_DIR, queue_name)
    if not os.path.exists(queue_path):
        raise HTTPException(status_code=404, detail="Queue not found")
    messages_file = os.path.join(queue_path, "messages.jsonl")
    # Read all messages
    messages = []
    if os.path.exists(messages_file):
        with open(messages_file, "r") as f:
            for line in f:
                line = line.strip()
                if line:
                    messages.append(json.loads(line))
    # If no messages, return 204
    if len(messages) == 0:
        return Response(status_code=204)
    # Remove and return first message
    consumed = messages.pop(0)
    # Write back remaining messages
    with open(messages_file, "w") as f:
        for msg in messages:
            f.write(json.dumps(msg) + "\n")
    return consumed


@app.get("/status")
def status():
    return {"status": "ok"}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=8000)
EOF"}

